namespace ghidra.app.plugin.core.decompile.actions;

using docking.widgets;
using docking.widgets;
using docking.widgets.fieldpanel.support;
using docking.widgets.search;

public class DecompilerSearchLocation : SearchLocation {

	private FieldLocation fieldLocation;
	private string textLine;

	public DecompilerSearchLocation(FieldLocation fieldLocation, int startIndexInclusive,
			int endIndexInclusive, string text, bool forwardDirection, string textLine,
			int lineNumber, SearchLocationContext context) : base(startIndexInclusive, endIndexInclusive, text, lineNumber, context)
    {
		this.fieldLocation = fieldLocation;
		this.textLine = textLine;
	}

	public FieldLocation getFieldLocation() {
		return fieldLocation;
	}

	public string getTextLine() {
		return textLine;
	}

	/* @Override */
	public CursorPosition getCursorPosition() {
		return new DecompilerCursorPosition(fieldLocation);
	}

	/* @Override */
	protected string fieldsToString() {
		return base.fieldsToString() + ", fieldLocation=" + fieldLocation;
	}

	public bool contains(FieldLocation other) {
		int line = getLineNumber();
		int otherLine = other.getIndex().intValue() + 1; // +1 for zero based
		if (line != otherLine) {
			return false;
		}

		int col = other.getCol();
		return contains(col);
	}
}
